let theta = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  frameRate(30);
}

function draw() {
  let bass = (typeof sub_bass !== undefined) ? sub_bass : 0;
  let perc = (typeof percussive !== undefined) ? percussive : 0;

  background(10, 10, 16);
  theta += 0.03 + bass * 0.04;

  push();
  translate(width / 2, height / 2);
  let baseLen = min(width, height) * 0.22 * (1.0 + bass * 0.3);
  for (let i = 0; i < 8; i++) {
    branch(baseLen, 6, theta, perc);
    rotate(PI / 4);
  }
  pop();
}

function branch(len, num, th, perc) {
  len = len / sqrt(2);
  num = num - 1;
  if (len > 2 && num > 0) {
    push();
    rotate(th);
    stroke(152, 247, 255, 220);
    strokeWeight(max(0.5, num / 2.5 + perc * 1.5));
    line(0, 0, 0, -len / 3);
    translate(0, -len / 3);
    branch(len, num, th, perc);
    pop();

    push();
    rotate(-th);
    stroke(255, 120, 180, 220);
    strokeWeight(max(0.5, num / 2.5 + perc * 1.5));
    line(0, 0, 0, -len);
    translate(0, -len);
    branch(len, num, th, perc);
    pop();

    push();
    rotate(-2 * th);
    stroke(120, 255, 200, 220);
    strokeWeight(max(0.5, num / 2.5 + perc * 1.5));
    line(0, 0, 0, -len / 6);
    translate(0, -len / 6);
    branch(len, num, th, perc);
    pop();
  }
}
